using System.Windows.Controls;using Crown___Sovereign.Data;namespace Crown___Sovereign.Views.UserControls.Gerencia.Finanzas;public partial class ResumenFinancieroControl:UserControl{public ResumenFinancieroControl(){InitializeComponent();var income=SampleData.Movimientos.Where(m=>m.Tipo=="Pago").Sum(m=>m.Monto);RevenueText.Text=$"Bs {income:N2}";PaymentsText.Text=SampleData.Movimientos.Count(m=>m.Tipo=="Pago").ToString();CashText.Text=SampleData.CajaAbierta?"Abierta":"Cerrada";}}
